import unittest

from textkit.duration import format_duration, parse_duration
from tests.test_cli import run


class DurationTest(unittest.TestCase):
    def test_parse(self):
        for s, n in [("1h30m", 5400), ("45s", 45), ("2h5s", 7205), ("90m", 5400)]:
            self.assertEqual(parse_duration(s), n)

    def test_parse_invalid(self):
        for s in ["", "1x", "30m1h", "1h1h", "1.5h", "h", "1h 30m"]:
            with self.assertRaises(ValueError):
                parse_duration(s)

    def test_format(self):
        for n, s in [(5400, "1h30m"), (7205, "2h5s"), (59, "59s"), (0, "0s")]:
            self.assertEqual(format_duration(n), s)
        with self.assertRaises(ValueError):
            format_duration(-1)

    def test_cli(self):
        self.assertEqual(run("dur", "1h30m"), (0, "5400\n", ""))
        self.assertEqual(run("dur", "5400"), (0, "1h30m\n", ""))
        code, _, err = run("dur", "30m1h")
        self.assertEqual(code, 2)
        self.assertTrue(err.startswith("error:"))
"""The README command table and the registry must agree."""
